.panel-details {
  margin-bottom: 10px;
  background: rgba(255, 245, 248, 0.55);
  border-radius: 14px;
  border: 1px solid #ffd0dd;
  overflow: hidden;
  transition: background 0.2s ease;
}
.panel-details[open] {
  background: rgba(255, 245, 248, 0.85);
}
.panel-summary {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 10px 14px;
  cursor: pointer;
  list-style: none;
  user-select: none;
  font-size: 13px;
  font-weight: 600;
  color: #b85070;
  background: transparent;
  transition: background 0.2s ease;
}
.panel-summary::-webkit-details-marker { display: none; }
.panel-summary:hover {
  background: rgba(255, 210, 220, 0.45);
}
.panel-summary::after {
  content: "▼";
  font-size: 10px;
  margin-left: auto;
  opacity: 0.6;
  transition: transform 0.2s ease;
}
.panel-details[open] > .panel-summary::after {
  transform: rotate(180deg);
}
.panel-details .preset-section {
  border: none;
  margin-bottom: 0;
  border-radius: 0;
  border-top: 1px solid #ffd0dd;
}

/* ========== 模型按钮美化 ========== */
.model-btn {
  flex: 1;
  min-width: 80px;
  font-weight: 600;
  letter-spacing: 0.3px;
  transition: all 0.25s ease;
}
.model-btn:nth-child(1) {
  background: linear-gradient(135deg, #1a2332 0%, #243447 100%) !important;
  border-color: #3a506b !important;
  color: #e0e8f0 !important;
}
.model-btn:nth-child(2) {
  background: linear-gradient(135deg, #3d2c24 0%, #4a3728 100%) !important;
  border-color: #6b5240 !important;
  color: #f0e0d0 !important;
}
.model-btn:nth-child(3) {
  background: linear-gradient(135deg, #2a2a4a 0%, #3a3a6a 100%) !important;
  border-color: #5a5a8a !important;
  color: #e0e0f8 !important;
}
.model-btn:hover {
  transform: translateY(-2px);
  filter: brightness(1.1);
}
