  const DEFAULT_PRESETS = ['DeepSeek', 'Claude', 'Gemini'];

  function buildPanelHTML() {
    let html = '';
    for (const [title, keywords] of Object.entries(PANELS)) {
      html += `<details class="panel-details" open><summary class="panel-summary">${title}</summary><div class="preset-section"><div class="toggle-grid ${keywords.length > 12 ? 'col-3' : ''}">`;
      keywords.forEach(kw => {
        const on = isKeywordOn(kw);
        html += `<div class="toggle-item${on ? ' is-on' : ''}" data-kw="${kw.replace(/"/g, '&quot;')}"><span>${kw}</span><span class="toggle-led"></span></div>`;
      });
      html += '</div></div></details>';
    }
    return html;
