    presetPanel.addEventListener(evt, e => e.stopPropagation());
  });

  function adjustDialog(dialog) {
    if (isMobile) return; // 移动端使用居中定位，无需翻转
    dialog.classList.remove('dialog-flip');
    void dialog.offsetHeight;
    const rect = dialog.getBoundingClientRect();
    if (rect.left < 0) dialog.classList.add('dialog-flip');
  }

  function showToast(text, type = 'info') {
    const toast = pdoc.createElement('div');
    toast.className = 'st-toast-message';
    toast.textContent = text;
    if (type === 'success') { toast.style.background = 'linear-gradient(145deg, #e8f5e9 0%, #c8e6c9 100%)'; toast.style.borderColor = '#81c784'; toast.style.color = '#2e7d32'; }
    else if (type === 'error') { toast.style.background = 'linear-gradient(145deg, #ffebee 0%, #ffcdd2 100%)'; toast.style.borderColor = '#e57373'; toast.style.color = '#c62828'; }
    pdoc.body.appendChild(toast);
    setTimeout(() => toast.remove(), 2000);
  }

  presetPanel.addEventListener('click', (e) => {
    const item = e.target.closest('.toggle-item');
    if (!item) return;
    if (!pdoc.querySelector('#completion_prompt_manager_list')) { showToast('请先打开预设面板', 'error'); return; }
    const kw = item.dataset.kw;
    if (item.classList.contains('is-on')) { ensureOff(kw); item.classList.remove('is-on'); }
    else { ensureOn(kw); item.classList.add('is-on'); }
  });

  function applyBuiltinPreset(modelName) {
    const preset = BUILTIN_PRESETS[modelName];
    if (!preset) { showToast(`⚠️ 方案 "${modelName}" 不存在`, 'error'); return; }
    if (!pdoc.querySelector('#completion_prompt_manager_list')) { showToast('请先打开预设面板', 'error'); return; }
    let changed = 0;
    for (const [kw, enabled] of Object.entries(preset)) {
      if (isKeywordOn(kw) !== enabled) {
        if (enabled) ensureOn(kw); else ensureOff(kw);
        changed++;
      }
    }
    showToast(`✅ 已切换至 ${modelName} (${changed}项)`, 'success');
    refreshPanelUI();
  }

  pdoc.querySelectorAll('.model-btn').forEach(btn => {
    btn.addEventListener('click', (e) => {
      e.stopPropagation();
      applyBuiltinPreset(btn.dataset.model);
    });
  });

  function getAllPlans() { try { return JSON.parse(localStorage.getItem('hana_st_presets') || '{}'); } catch(e) { return {}; } }

  function loadPlan(name) {
    const plan = getAllPlans()[name];
    if (!plan?.items?.length) { showToast('方案为空或不存在', 'error'); return; }
    if (!pdoc.querySelector('#completion_prompt_manager_list')) { showToast('请先打开预设面板', 'error'); return; }
    plan.items.forEach(item => { if (item.enabled) ensureOn(item.name); else ensureOff(item.name); });
    refreshPanelUI();
    showToast(`✅ 方案 "${name}" 已加载`, 'success');
  }

  function deletePlan(name) {
    const plans = getAllPlans();
    delete plans[name];
    localStorage.setItem('hana_st_presets', JSON.stringify(plans));
    refreshPlanList();
    showToast('方案已删除');
  }

  function refreshPanelUI() {
    const c = pdoc.getElementById(`${PET_ID}-panel-content`);
    if (c) c.innerHTML = buildPanelHTML();
  }

  function refreshPlanList() {
    const container = pdoc.getElementById('preset-list-container');
    if (!container) return;
    const names = Object.keys(getAllPlans()).filter(n => !DEFAULT_PRESETS.includes(n));
    container.innerHTML = names.length ? '' : '<div class="preset-empty">暂无自定义方案</div>';
    names.forEach(name => {
      const item = pdoc.createElement('div');
      item.className = 'preset-item';
      item.innerHTML = `<span class="preset-item-name">${name}</span><span style="display:flex;gap:4px;">
        <button class="preset-item-delete" style="background:#e8f0e8;color:#5a8a5a;">▶ 读取</button>
        <button class="preset-item-delete">🗑️</button>
      </span>`;
      item.querySelector('button:first-child').addEventListener('click', e => { e.stopPropagation(); if (confirm(`读取方案 "${name}"？`)) loadPlan(name); });
      item.querySelector('button:last-child').addEventListener('click', e => { e.stopPropagation(); if (confirm(`删除方案 "${name}"？`)) deletePlan(name); });
      container.appendChild(item);
    });
  }

  pdoc.getElementById('preset-refresh-btn').addEventListener('click', e => { e.stopPropagation(); refreshPlanList(); showToast('列表已刷新'); });
  pdoc.getElementById('preset-save-btn').addEventListener('click', e => {
    e.stopPropagation();
    const name = prompt('输入方案名称：');
    if (!name) return;
    const items = [];
    pdoc.querySelectorAll('.toggle-item').forEach(item => {
      items.push({ name: item.dataset.kw, enabled: item.classList.contains('is-on') });
    });
    const plans = getAllPlans();
    plans[name] = { items, savedAt: new Date().toISOString() };
    localStorage.setItem('hana_st_presets', JSON.stringify(plans));
    refreshPlanList();
    showToast(`✅ 方案 "${name}" 已保存`, 'success');
  });

  let bubbleVisible = false;

  function showBubble() { bubble.style.display = 'block'; bubbleVisible = true; chatBubble.style.display = 'none'; adjustDialog(bubble); }
  function hideBubble() { bubble.style.display = 'none'; bubbleVisible = false; }

  function showPresetPanel() {
    hideBubble();
    chatBubble.style.display = 'none';
    presetPanel.style.display = 'flex';
    refreshPanelUI();
    refreshPlanList();
    adjustDialog(presetPanel);
  }
  function hidePresetPanel() { presetPanel.style.display = 'none'; }

  pdoc.getElementById('preset-panel-close').addEventListener('click', e => { e.stopPropagation(); hidePresetPanel(); });
