  bubble.querySelector('#pet-btn-preset').addEventListener('click', e => { e.stopPropagation(); hideBubble(); showPresetPanel(); });

  function minimizeHana() { pet.classList.remove('interactive'); hideBubble(); chatBubble.style.display = 'none'; presetPanel.style.display = 'none'; }
  function enterInteractive() { pet.classList.add('interactive'); hideBubble(); presetPanel.style.display = 'none'; }

  function showChatBubble() {
    if (!pet.classList.contains('interactive')) return;
    const msg = chatMessages[Math.floor(Math.random() * chatMessages.length)];
    chatBubble.querySelector('#chat-message').textContent = msg.text;
    chatBubble.style.display = 'block';
    hideBubble();
    adjustDialog(chatBubble);
  }
  chatBubble.addEventListener('click', e => { e.stopPropagation(); chatBubble.style.display = 'none'; });

  pdoc.addEventListener('click', e => {
    if (!pet.contains(e.target)) {
      hideBubble();
      chatBubble.style.display = 'none';
    }
  });

  refreshPlanList();

  // ========== 拖拽 ==========
  let drag = false, ox = 0, oy = 0, moved = false;
  const dragHandleSakura = pdoc.getElementById(`${PET_ID}-sakura`);
  const dragHandlePetImg = pdoc.getElementById(`${PET_ID}-pet-img`);

  function savePos() {
    const d = JSON.stringify({ x: parseInt(pet.style.left), y: parseInt(pet.style.top) });
    localStorage.setItem('stImagePetPos', d);
    try { insertOrAssignVariables({ 'stImagePetPos': d }, { type: 'global' }); } catch (_) {}
  }

  function startDrag(cx, cy) { drag = true; moved = false; const r = pet.getBoundingClientRect(); ox = cx - r.left; oy = cy - r.top; pet.style.transition = 'none'; }
  function moveDrag(cx, cy) { if (!drag) return; moved = true; pet.style.left = Math.max(4, Math.min(cx - ox, pwin.innerWidth - 52)) + 'px'; pet.style.top = Math.max(4, Math.min(cy - oy, pwin.innerHeight - 52)) + 'px'; }
  function endDrag() { if (!drag) return; drag = false; pet.style.transition = ''; if (moved) savePos(); }

  function bindDragHandle(el) {
    if (!el) return;
    el.addEventListener('mousedown', e => { startDrag(e.clientX, e.clientY); e.preventDefault(); });
    el.addEventListener('touchstart', e => { startDrag(e.touches[0].clientX, e.touches[0].clientY); }, { passive: true });
  }
  bindDragHandle(dragHandleSakura);
  bindDragHandle(dragHandlePetImg);

  pdoc.addEventListener('mousemove', e => moveDrag(e.clientX, e.clientY));
  pdoc.addEventListener('mouseup', endDrag);
  pdoc.addEventListener('touchmove', e => { if (!drag) return; moveDrag(e.touches[0].clientX, e.touches[0].clientY); e.preventDefault(); }, { passive: false });
  pdoc.addEventListener('touchend', endDrag);
  pdoc.addEventListener('touchcancel', endDrag);

  let clickTimer = null;
  function bindClickHandle(el) {
    if (!el) return;
    el.addEventListener('click', e => {
      if (moved) { moved = false; return; }
      if (e.target.closest('.pet-dialog')) return;
      if (clickTimer) { clearTimeout(clickTimer); clickTimer = null; if (pet.classList.contains('interactive')) showChatBubble(); }
      else { clickTimer = setTimeout(() => { clickTimer = null; bubbleVisible ? hideBubble() : showBubble(); }, 250); }
    });
  }
  bindClickHandle(dragHandleSakura);
  bindClickHandle(dragHandlePetImg);

  function cleanup() {
    const els = pdoc.querySelectorAll('[id^="st-image-pet"]');
    els.forEach(el => el.remove());
    pwin.__hanaRunning = false;
  }
  window.addEventListener('pagehide', cleanup);
  window.addEventListener('unload', cleanup);
  window.addEventListener('beforeunload', cleanup);

  pwin.__hanaRunning = true;
  console.log('🌸 繁花菜单已加载 - 美化版');
})();

